<script>$(function(){var t=$('#stock-movement-table'),x=$.fn.dataTable.render.text(),wmsPlaces={{ \App\Modules\Wms\Support\WmsDecimal::places() }},hasValue=function(v){return v!==null&&v!==undefined&&v!=='';},fmt=function(v){if(!hasValue(v))return '-';var n=Number(v);return Number.isFinite(n)?n.toLocaleString('en-US',{minimumFractionDigits:wmsPlaces,maximumFractionDigits:wmsPlaces}):'-';},colored=function(cls,v){return '<span class="'+cls+'">'+x.display(fmt(v))+'</span>';};var dt=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{order:[[1,'asc']],ajax:{url:t.data('url'),data:function(d){d.item_id={{ $item->id }};d.date_from=$('#stock-detail-from').val();d.date_to=$('#stock-detail-to').val();}},buttons:[window.erpExcelButton(t)],columns:[{data:null,orderable:false,searchable:false,render:function(v,type,row,meta){return type==='display'?meta.row+meta.settings._iDisplayStart+1:'';}},{data:'movement_datetime',name:'wms_stock_movements.business_date',render:x.display},{data:'source_reference',name:'wms_stock_movements.source_reference',orderable:false,render:function(v){return x.display(v||'-')}},{data:'movement_type_label',name:'wms_stock_movements.movement_type',orderable:false,render:x.display},{data:null,orderable:false,searchable:false,render:function(v,type,row){return type==='display'?colored('text-success',row.direction==='IN'?row.base_quantity:'-'):' ';}},{data:'unit_cost',orderable:false,searchable:false,className:'text-end',render:function(v,type){return type==='display'?colored('text-success',hasValue(v)?v:'-'):v;}},{data:'movement_total',orderable:false,searchable:false,className:'text-end',render:function(v,type){return type==='display'?colored('text-success',v):v;}},{data:null,orderable:false,searchable:false,render:function(v,type,row){return type==='display'?colored('text-danger',row.direction==='OUT'?row.base_quantity:'-'):' ';}},{data:'unit_cost',orderable:false,searchable:false,className:'text-end',render:function(v,type,row){return type==='display'?colored('text-danger',row.direction==='OUT'&&hasValue(row.unit_cost)?row.unit_cost:'-'):v;}},{data:null,orderable:false,searchable:false,render:function(v,type,row){return type==='display'?colored('text-danger',row.direction==='OUT'?row.movement_total:'-'):' ';}},{data:'running_balance',orderable:false,searchable:false,className:'text-end',render:function(v,type){return type==='display'?colored('text-info',v):v;}},{data:'unit_cost',orderable:false,searchable:false,className:'text-end',render:function(v,type){return type==='display'?colored('text-info',hasValue(v)?v:'-'):v;}},{data:'running_value',orderable:false,searchable:false,className:'text-end',render:function(v,type){return type==='display'?colored('text-info',v):v;}},{data:null,orderable:false,searchable:false,render:function(){return '<span class="text-secondary">-</span>';}}],drawCallback:function(s){var b=s.json&&s.json.balance||{},o=s.json&&s.json.opening_balance||{};$('#stock-opening').text(o.on_hand||'-');$('#stock-closing').text(b.on_hand||'-');$('#stock-on-hand').text(b.on_hand||'-');$('#stock-reserved').text(b.reserved||'-');$('#stock-available').text(b.available||'-')}}));$('#stock-detail-apply').on('click',function(){var from=$('#stock-detail-from').val(),to=$('#stock-detail-to').val();if(from&&to&&from>to){Swal.fire({icon:'error',text:'วันที่เริ่มต้นต้องไม่มากกว่าวันที่สิ้นสุด'});return;}dt.ajax.reload()});});</script>
